<?php declare(strict_types=1);
function ax(PDO $db,string $sql):array{try{return$db->query($sql)->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){return[];}} function ac(PDO $db,string $sql):int{try{return(int)$db->query($sql)->fetchColumn();}catch(Throwable){return 0;}}
$ads=ax($db,'SELECT * FROM ads_settings ORDER BY id DESC');$total=ac($db,'SELECT COUNT(*) FROM ads_settings');$on=ac($db,'SELECT COUNT(*) FROM ads_settings WHERE enabled=1');
?>
<div class="av4-page"><div class="av4-stat-grid"><div class="av4-stat"><b><?=number_format($total)?></b><span>Total placements</span></div><div class="av4-stat green"><b><?=number_format($on)?></b><span>Active</span></div><div class="av4-stat orange"><b><?=number_format($total-$on)?></b><span>Disabled</span></div><div class="av4-stat purple"><b><?=number_format($total?round($on/$total*100):0)?>%</b><span>Active rate</span></div></div>
<div class="av4-card"><div class="av4-head"><div><h2>📣 Ads Manager</h2><p>Manage placement keys and ad network code.</p></div><span class="av4-chip green"><?=number_format($on)?> ACTIVE</span></div><form class="av4-form" method="post" action="/smart-toolz/admin/admin-actions.php"><input type="hidden" name="action" value="ad_save"><input type="hidden" name="back" value="ads"><input type="hidden" name="csrf" value="<?=av4h(adminCsrf())?>"><input type="hidden" name="id" value="0"><div><label>Placement key</label><input name="ad_key" placeholder="728x90" required></div><div><label>Status</label><select name="enabled"><option value="1">Enabled</option><option value="0">Disabled</option></select></div><div class="full"><label>Ad code</label><textarea name="ad_code" placeholder="Paste ad network code…" required></textarea></div><div class="full"><button class="av4-btn primary">＋ Add Placement</button></div></form></div>
<div class="av4-card"><div class="av4-head"><div><h2>Placement inventory</h2><p>Current database configuration.</p></div></div><div class="av4-table"><table><thead><tr><th>ID</th><th>Key</th><th>Status</th><th>Code preview</th><th>Updated</th><th>Action</th></tr></thead><tbody><?php foreach($ads as $r):?><tr><td><?=av4h($r['id']??'')?></td><td><b><?=av4h($r['ad_key']??'')?></b></td><td><span class="av4-tag <?=!empty($r['enabled'])?'green':'gray'?>"><?=!empty($r['enabled'])?'ACTIVE':'OFF'?></span></td><td class="mono"><?=av4h(substr((string)($r['ad_code']??''),0,180))?></td><td><?=av4h($r['updated_at']??'')?></td><td><form method="post" action="/smart-toolz/admin/admin-actions.php" onsubmit="return confirm('Delete this placement?')"><input type="hidden" name="action" value="ad_delete"><input type="hidden" name="back" value="ads"><input type="hidden" name="csrf" value="<?=av4h(adminCsrf())?>"><input type="hidden" name="id" value="<?=av4h($r['id']??0)?>"><button class="av4-btn danger small">Delete</button></form></td></tr><?php endforeach;if(!$ads):?><tr><td colspan="6" class="empty">No placements configured.</td></tr><?php endif;?></tbody></table></div></div></div>
